-- Legal sources register: the list of sources (Acts, regulations, official guidance) the app relies on, with the provisions read, version, date and status. Seed generated from the Marae Governance and Compliance Framework source register (22 Nov 2026, 30 rows). Additive and idempotent. Read-only for signed-in users.
create table if not exists public.legal_sources (
  key text primary key,
  name text not null,
  kind text not null,
  provisions_read text not null,
  version_and_date_read text not null,
  status text not null,
  url text,
  notes text,
  checked_on date not null default date '2026-11-22'
);
alter table public.legal_sources enable row level security;
drop policy if exists legal_sources_read on public.legal_sources;
create policy legal_sources_read on public.legal_sources for select to authenticated using (true);
on conflict (key) do update set name=excluded.name, kind=excluded.kind, provisions_read=excluded.provisions_read, version_and_date_read=excluded.version_and_date_read, status=excluded.status, url=excluded.url, notes=excluded.notes, checked_on=excluded.checked_on;
